
jQuery(document).ready(function(b){var a=b("#access-permission-select").val();b(".edit-post-protection, .save-post-protection, .cancel-post-protection").click(function(c){c.preventDefault();if(b(this).hasClass("cancel-post-protection")){b("#access-permission-select").val(a)}else{if(b(this).hasClass("save-post-protection")){a=b("#access-permission-select").val();b("#post-protection-label").text(b("#access-permission-select option[value="+b("#access-permission-select").val()+"]").text());if(b("#access-permission-select").val()=="all"){b("#access-icon").removeClass("access-icon").addClass("access-all-icon")}else{b("#access-icon").removeClass("access-all-icon").addClass("access-icon")}}}b("#post-protection-field").slideToggle("fast")})});